contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint256 beforeC = address(c).balance;
        uint256 beforeCallerBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 afterC = address(c).balance;
        uint256 afterCallerBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(
            (reverted && afterCallerBal == beforeCallerBal && afterC == beforeC) ||
            (!reverted && afterCallerBal == 0 && afterC <= beforeC)
        );
    }

    receive() external payable {}
}

