pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint256 beforeC = address(c).balance;
        uint256 beforeCallerBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeCallerBal = __r; } catch { return; }
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        uint256 afterC = address(c).balance;
        uint256 afterCallerBal;
        try c.balances(address(this)) returns (uint256 __r) { afterCallerBal = __r; } catch { return; }
        assertTrue((reverted && afterCallerBal == beforeCallerBal && afterC == beforeC) ||
            (!reverted && afterCallerBal == 0 && afterC <= beforeC));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
